// Outbound links to the source. Pure; tests/affiliate.test.ts.
//
// A click is logged whether or not it earns anything; `tracked` says whether
// the link carries a programme tag that can. AliExpress Portals links must be
// generated by their API (aliexpress.affiliate.link.generate), so without that
// key the link is honest-but-untracked rather than a hand-rolled guess.

export interface AffiliateEnv {
  AMAZON_ASSOCIATE_TAG?: string;
  EBAY_EPN_CAMPAIGN_ID?: string;
  ALIEXPRESS_TRACKING_ID?: string;
}

/**
 * Per-click sub-ID the programme echoes back in its report (Amazon `ascsubtag`,
 * eBay EPN `customid`), so a commission can be tied to the click that earned it.
 */
export function subIdFor(clickId: number): string {
  return `L${clickId}`;
}

export function clickIdFromSubId(subId: string | null | undefined): number | null {
  const m = /^L(\d{1,12})$/.exec((subId ?? "").trim());
  return m ? Number(m[1]) : null;
}

export function affiliateUrl(
  platform: string,
  url: string,
  env: AffiliateEnv,
  subId?: string,
): { url: string; tracked: boolean } {
  let u: URL;
  try {
    u = new URL(url);
  } catch {
    return { url, tracked: false };
  }
  if (platform === "AMAZON" && env.AMAZON_ASSOCIATE_TAG) {
    u.searchParams.set("tag", env.AMAZON_ASSOCIATE_TAG);
    if (subId) u.searchParams.set("ascsubtag", subId);
    return { url: u.toString(), tracked: true };
  }
  if (platform === "EBAY" && env.EBAY_EPN_CAMPAIGN_ID) {
    // eBay Partner Network smart-link parameters.
    u.searchParams.set("mkcid", "1");
    u.searchParams.set("mkrid", "711-53200-19255-0");
    u.searchParams.set("siteid", "0");
    u.searchParams.set("campid", env.EBAY_EPN_CAMPAIGN_ID);
    u.searchParams.set("toolid", "10001");
    u.searchParams.set("mkevt", "1");
    if (subId) u.searchParams.set("customid", subId);
    return { url: u.toString(), tracked: true };
  }
  if (platform === "ALIEXPRESS" && env.ALIEXPRESS_TRACKING_ID) {
    // Real Portals links come from the API; this only marks the click so it can
    // be reconciled — tracked stays false until the API adapter generates it.
    return { url, tracked: false };
  }
  return { url, tracked: false };
}

/** Only http(s) links to known retailer hosts may be redirected to — no open redirect. */
const ALLOWED_HOSTS = [
  // Explicit TLDs: a `[a-z.]+` suffix would accept amazon.com.evil.io.
  /(^|\.)amazon\.(com|ca|cn|de|es|fr|in|it|nl|pl|se|sg|ae|sa|co\.uk|co\.jp|com\.au|com\.mx|com\.br|com\.tr|com\.be)$/,
  /(^|\.)ebay\.(com|ca|de|es|fr|it|nl|pl|ch|at|ie|ph|co\.uk|com\.au|com\.hk|com\.sg|com\.my)$/,
  /(^|\.)aliexpress\.(com|us)$/,
  /(^|\.)alibaba\.com$/,
  /(^|\.)1688\.com$/,
  /(^|\.)taobao\.com$/,
  /(^|\.)tmall\.com$/,
  /(^|\.)jd\.com$/,
  /(^|\.)yangkeduo\.com$/,
  /(^|\.)pinduoduo\.com$/,
  /^online-price-watch\.consumer\.org\.hk$/,
];

export function isSafeRedirect(url: string): boolean {
  try {
    const u = new URL(url);
    if (u.protocol !== "https:" && u.protocol !== "http:") return false;
    return ALLOWED_HOSTS.some((re) => re.test(u.hostname));
  } catch {
    return false;
  }
}
